pub trait Greet {
    fn greet(&self) -> String;
}

pub struct English;
pub struct French;

impl Greet for English {
    fn greet(&self) -> String {
        "Hello".into()
    }
}

impl Greet for French {
    fn greet(&self) -> String {
        "Bonjour".into()
    }
}

mod greeter;
mod greeting;

use greeter::Greet;

fn main() {
    let english = greeter::English;
    println!("{} {}", english.greet(), greeting::hello("world"));
}
